#include "net_tls.h"
#include "net_tcp.h"
#include "net_dns.h"
#include "crypto_rng.h"
#include <stddef.h>
#include <stdint.h>
#define NET_TLS_MAX_HOSTNAME 253U
#define NET_TLS_IO_TIMEOUT_MS 10000U
#define NET_TLS_ENTROPY_BYTES 48U
#define NET_TLS_HTTP_REQUEST_MAX 1024U
static int valid_host(const char *h){size_t n=0;if(!h||!*h)return 0;while(h[n]){unsigned char c=(unsigned char)h[n];if(++n>NET_TLS_MAX_HOSTNAME)return 0;if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='.'))return 0;}return h[0]!='.'&&h[n-1U]!='.'&&h[0]!='-'&&h[n-1U]!='-';}
static int tcp_read(void *ctx,unsigned char *buf,size_t len){net_tls_client_t*c=ctx;if(!c||!c->active||!buf||!len)return -1;if(len>0x7FFFFFFFU)len=0x7FFFFFFFU;return net_tcp_receive(c->device,buf,len,NET_TLS_IO_TIMEOUT_MS);}
static int tcp_write(void *ctx,const unsigned char *buf,size_t len){net_tls_client_t*c=ctx;size_t off=0;if(!c||!c->active||(!buf&&len)||len>0x7FFFFFFFU)return -1;while(off<len){size_t n=len-off;if(n>1400U)n=1400U;if(!net_tcp_send(c->device,buf+off,n,NET_TLS_IO_TIMEOUT_MS))return -1;off+=n;}return (int)len;}
int net_tls_connect(net_tls_client_t*c,net_device_t*d,const char*host,uint16_t port,uint32_t timeout,const br_x509_trust_anchor*anchors,size_t count,uint32_t days,uint32_t seconds){uint32_t ip;unsigned char entropy[NET_TLS_ENTROPY_BYTES];if(!c||!d||!d->link_up||!d->ipv4_configured||!valid_host(host)||!port||timeout<500U||timeout>30000U||!anchors||!count||seconds>=86400U)return 0;if(!net_dns_resolve(d,host,&ip,timeout)||!net_tcp_connect(d,ip,port,timeout))return 0;for(size_t i=0;i<sizeof(entropy);i++)entropy[i]=0;if(!crypto_rng_fill(entropy,sizeof(entropy))){net_tcp_close(d);return 0;}*c=(net_tls_client_t){0};c->device=d;br_ssl_client_init_full(&c->ssl,&c->x509,anchors,count);br_x509_minimal_set_time(&c->x509,days,seconds);br_ssl_engine_inject_entropy(&c->ssl.eng,entropy,sizeof(entropy));for(size_t i=0;i<sizeof(entropy);i++)entropy[i]=0;br_sslio_init(&c->io,&c->ssl.eng,tcp_read,c,tcp_write,c);c->active=1U;if(!br_ssl_client_reset(&c->ssl,host,0)||!br_sslio_flush(&c->io)){c->active=0U;net_tcp_close(d);return 0;}return 1;}
int net_tls_write(net_tls_client_t*c,const void*data,size_t n){if(!c||!c->active||(!data&&n)||n>0x7FFFFFFFU)return -1;if(!br_sslio_write_all(&c->io,data,n)||!br_sslio_flush(&c->io))return -1;return (int)n;}
int net_tls_read(net_tls_client_t*c,void*data,size_t cap){if(!c||!c->active||!data||!cap||cap>0x7FFFFFFFU)return -1;int n=br_sslio_read(&c->io,data,cap);return n<0?-1:n;}
void net_tls_close(net_tls_client_t*c){if(!c||!c->active)return;(void)br_sslio_close(&c->io);c->active=0U;net_tcp_close(c->device);c->device=0;}
static int append(char*d,size_t cap,size_t*used,const char*s,size_t n){if(!d||!used||(!s&&n)||*used>cap||n>cap-*used)return 0;for(size_t i=0;i<n;i++)d[(*used)++]=s[i];return 1;}
int net_https_get(net_device_t*d,const char*host,const char*path,uint16_t port,const br_x509_trust_anchor*anchors,size_t count,uint32_t days,uint32_t seconds,void*response,size_t cap,uint32_t timeout){static net_tls_client_t client;char req[NET_TLS_HTTP_REQUEST_MAX];size_t used=0,pathlen=0,hostlen=0;int result=-1;if(!d||!valid_host(host)||!path||path[0]!='/'||!response||!cap||cap>0x7FFFFFFFU)return -1;while(path[pathlen]){unsigned char c=(unsigned char)path[pathlen];if(c<0x20U||c==0x7FU||++pathlen>=sizeof(req))return -1;}while(host[hostlen])hostlen++;if(!append(req,sizeof(req),&used,"GET ",4U)||!append(req,sizeof(req),&used,path,pathlen)||!append(req,sizeof(req),&used," HTTP/1.1\r\nHost: ",17U)||!append(req,sizeof(req),&used,host,hostlen)||!append(req,sizeof(req),&used,"\r\nConnection: close\r\nUser-Agent: VantaOS\r\nAccept: */*\r\n\r\n",sizeof("\r\nConnection: close\r\nUser-Agent: VantaOS\r\nAccept: */*\r\n\r\n")-1U))return -1;if(!net_tls_connect(&client,d,host,port,timeout,anchors,count,days,seconds))return -1;if(net_tls_write(&client,req,used)<0)goto done;result=net_tls_read(&client,response,cap);if(result<=0)result=-1;done:net_tls_close(&client);return result;}
